+// Sites (kitchens). Every location belongs to one site and a batch belongs
+// to the site of its location. Functions that take a `site` only see that
+// site's stock; without one they see every site (jobs, tools, exports).
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and belongs to `site` (any site when undefined). */
+export function locationInSite(store, location, site) {
+  return store.data.locations.some((l) => l.id === location && (site === undefined || l.site === site));
+}
+
+/** A test for batches: is this batch in `site`? Always true when `site` is undefined. */
+export function batchInSite(store, site) {
+  if (site === undefined) return () => true;
+  const siteOf = new Map(store.data.locations.map((l) => [l.id, l.site]));
+  // A batch whose location is not on file (old data) counts as the default site.
+  return (batch) => (siteOf.get(batch.location) ?? DEFAULT_SITE) === site;
+}
