@@ -0,0 +1,115 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createOrder, receiveOrder, sendOrder } from "../src/domain/orders.js";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+const at = "2026-10-28T08:00:00Z";
+
+// Puts 3 kg of onion (item 1) into the annex fridge; returns the new batch.
+function stockAnnex(store) {
+  const order = createOrder(store, { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] }, { today: "2026-10-27" });
+  sendOrder(store, order.id);
+  return receiveOrder(store, order.id, [{ lot: "AX-1", expires: "2026-10-29", location: "annex-fridge" }], { at, site: "annex" })[0];
+}
+
+test("the seed has two sites and the annex fridge", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites, [{ id: "main", name: "Main kitchen" }, { id: "annex", name: "Annex kitchen" }]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex", kind: "fridge" });
+  assert.ok(store.data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "cellar" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /cellar/);
+});
+
+test("no header means the main site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  const plain = await handle({ path: "/batches" });
+  const main = await handle({ path: "/batches", headers: { "x-larder-site": "main" } });
+  assert.deepEqual(plain.body, main.body);
+  assert.equal(plain.body.length, 9);
+});
+
+test("batches and stock on hand only show the request's site", async () => {
+  const { handle, store } = app();
+  const batch = stockAnnex(store);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ path: "/items" })).body.find((i) => i.id === 1).onHand, 10);
+  assert.equal((await handle({ path: "/items", headers: ANNEX })).body.find((i) => i.id === 1).onHand, 3);
+  const item = (await handle({ path: "/items/1", headers: ANNEX })).body;
+  assert.equal(item.onHand, 3);
+  assert.deepEqual(item.batches.map((b) => b.id), [batch.id]);
+  const wasted = await handle({ method: "POST", path: `/batches/${batch.id}/waste`, body: { qty: 1 } });
+  assert.equal(wasted.status, 404);
+  assert.equal(batch.qty, 3);
+});
+
+test("cooking only uses the request's site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("alerts and stock value are per site", async () => {
+  const { handle, store } = app();
+  const batch = stockAnnex(store);
+  const main = (await handle({ path: "/alerts" })).body;
+  const annex = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.ok(main.expiring.every((b) => b.id !== batch.id));
+  assert.deepEqual(annex.expiring.map((b) => b.id), [batch.id]);
+  assert.ok(annex.lowStock.some((i) => i.name === "flour"));
+  assert.equal(annex.lowStock.find((i) => i.name === "onion").qty, 3);
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 540);
+  const all = (await handle({ path: "/reports/stock-value" })).body.totalCents;
+  assert.equal((await handle({ path: "/reports/stock-value", headers: { "x-larder-site": "main" } })).body.totalCents, all);
+});
+
+test("stock-takes stay inside their site", async () => {
+  const { handle, store } = app();
+  const batch = stockAnnex(store);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).body.error.code, "unknown_location");
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: batch.id, counted: 2 } });
+  const done = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(done.body.lines, [{ batchId: batch.id, expected: 3, counted: 2, diff: -1 }]);
+});
+
+test("an order is received into the request's site", async () => {
+  const { handle, store } = app();
+  const order = createOrder(store, { supplierId: 1, lines: [{ itemId: 4, qty: 1 }] }, { today: "2026-10-27" });
+  sendOrder(store, order.id);
+  const lots = [{ lot: "X", expires: null, location: "annex-fridge" }];
+  const wrong = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  assert.equal(order.state, "sent");
+  assert.equal((await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots } })).status, 200);
+});
+
+test("items, suppliers and dishes are shared", async () => {
+  const { handle } = app();
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"])
+    assert.deepEqual((await handle({ path, headers: ANNEX })).body, (await handle({ path })).body);
+  assert.equal((await handle({ path: "/items", headers: ANNEX })).body.length, 6);
+});
+
+test("the nightly job queues one low-stock notice per site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  assert.ok(store.data.outbox.some((m) => m.key === "low:2026-10-28:annex"));
+});
